import json
def format_ts(rows, var_name):
    lines = ["import { ExcelRowInput } from '../types';", "", f"export const {var_name}: ExcelRowInput[] = ["]
    for r in rows:
        no, date, contact, phone, resolve, status, assigned, answeredAt, firstResp, agentReply, source, adSource, remarks, sop = r
        obj = {
            "no": no,
            "date": date,
            "contact": contact,
            "phone": phone,
            "resolve": resolve,
            "status": status,
            "assigned": assigned,
            "answeredAt": answeredAt,
            "firstResponseTime": firstResp,
            "agentFirstReplyTime": agentReply,
            "source": source,
            "adSource": adSource,
            "remarks": remarks,
            "sop": sop
        }
        lines.append(f"  {json.dumps(obj, ensure_ascii=False)},")
    lines.append("];")
    lines.append("")
    return "\n".join(lines)

with open("src/data/leadsAugustPart2.ts", "w", encoding="utf-8") as f:
    f.write(format_ts(P2_ROWS, "EXCEL_LEADS_AUGUST_PART2"))

print(f"leadsAugustPart2.ts written: {len(P2_ROWS)} rows")
